public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        if (args[i] instanceof Class<?>) {
            result[i] = (Class<?>) args[i];
        } else if (args[i] instanceof ParameterizedType) {
            result[i] = (Class<?>) ((ParameterizedType) args[i]).getRawType();
        } else {
            // Cannot resolve type variable or wildcard
            return null;
        }
    }
    return result;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current index mapping for the specified table
    Mappings currentMapping = getCurrentMapping(tableName);
    // Prepare a new Mappings instance to hold the differences
    Mappings diff = new Mappings();
    // Iterate over all fields in the current mapping
    for (String fieldName : currentMapping.getFieldNames()) {
        // Skip the special _source field to avoid update conflicts
        if ("_source".equals(fieldName)) {
            continue;
        }
        // If the field does not exist in the history mapping, add it to the diff
        if (!mappings.containsField(fieldName)) {
            diff.addField(fieldName, currentMapping.getField(fieldName));
        }
    }
    return diff;
}

