        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        byte[] buffer = current.getBuffer();
        int len = current.getSize();
        out.write(buffer, 0, len);
        totalSize += len;
        current = current.getNext();
    }
    return totalSize;
}

