            }
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // make it odd
    }
    int limit = desiredCapacity >= 1000 ? (int) (desiredCapacity * 1.11) : Integer.MAX_VALUE;
    while (candidate <= limit) {
        boolean prime = true;
        if (candidate <= 3) {
            prime = candidate > 1;
        } else {
            if (candidate % 2 == 0 || candidate % 3 == 0) {
                prime = false;
            } else {
                for (int i = 5; i * i <= candidate; i += 6) {
                    if (candidate % i == 0 || candidate % (i + 2) == 0) {
                        prime = false;
                        break;
                    }
                }
            }
        }
        if (prime) {
            return candidate;
        }
        candidate += 2; // skip even numbers
    }
    return desiredCapacity;
}

