protected int removeUnusedNodes(){
    int removed = 0;
    if (root == null) return 0;
    java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()){
        Category current = stack.pop();
        java.util.Iterator<Category> it = current.getChildren().iterator();
        while (it.hasNext()){
            Category child = it.next();
            if (!child.isActive()){
                it.remove();
                removed++;
            } else {
                stack.push(child);
            }
        }
    }
    return removed;
}

