final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    int pos = 10; // start of constant pool (after magic, minor, major, constant_pool_count)
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = classFileBuffer[pos] & 0xFF;
        pos++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = ((classFileBuffer[pos] & 0xFF) << 8) | (classFileBuffer[pos + 1] & 0xFF);
                pos += 2 + len;
                break;
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
                pos += 4;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                pos += 8;
                i++; // these take up two entries in the constant pool
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
                pos += 2;
                break;
            case 9: // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
                pos += 4;
                break;
            default:
                throw new IllegalArgumentException("Invalid constant pool tag: " + tag);
        }
    }
    int tag = classFileBuffer[pos] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
    }
    pos++;
    int length = ((classFileBuffer[pos] & 0xFF) << 8) | (classFileBuffer[pos + 1] & 0xFF);
    pos += 2;
    if (length > charBuffer.length) {
        throw new IllegalArgumentException("charBuffer too small for UTF-8 string of length " + length);
    }
    byte[] bytes = new byte[length];
    System.arraycopy(classFileBuffer, pos, bytes, 0, length);
    String s = new String(bytes, "UTF-8");
    s.getChars(0, s.length(), charBuffer, 0);
    return s;
}

