int function (final String name,final String descriptor) {
    // Search for an existing CONSTANT_NameAndType_info with the same name and descriptor
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantPoolEntry entry = constantPool.get(i);
        if (entry instanceof NameAndTypeInfo) {
            NameAndTypeInfo nt = (NameAndTypeInfo) entry;
            if (nt.getName().equals(name) && nt.getDescriptor().equals(descriptor)) {
                return i; // Return the index of the existing entry
            }
        }
    }
    // No matching entry found; create a new one
    NameAndTypeInfo newEntry = new NameAndTypeInfo(name, descriptor);
    constantPool.add(newEntry);
    return constantPool.size() - 1; // Return the index of the newly added entry
}

private String unescapeId(String input){
    if (input == null) return null;
    int len = input.length();
    if (len >= 2 && input.charAt(0) == '"' && input.charAt(len-1) == '"') {
        input = input.substring(1, len-1);
        len = input.length();
    }
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(++i);
            switch (next) {
                case 'n': sb.append('\n'); break;
                case 't': sb.append('\t'); break;
                case 'r': sb.append('\r'); break;
                case 'b': sb.append('\b'); break;
                case 'f': sb.append('\f'); break;
                case '\\': sb.append('\\'); break;
                case '\"': sb.append('\"'); break;
                case '\'': sb.append('\''); break;
                case 'x':
                    if (i + 2 < len) {
                        String hex = input.substring(i+1, i+3);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 2;
                        } catch (NumberFormatException e) {
                            sb.append('x');
                        }
                    } else {
                        sb.append('x');
                    }
                    break;
                default:
                    sb.append(next);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

