public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (name == null) {
        return;
    }
    int len = name.length();
    if (nameStart < 0) {
        nameStart = 0;
    }
    if (nameStart >= len) {
        return;
    }
    boolean next = true;
    for (int i = nameStart; i < len; i++) {
        char c = name.charAt(i);
        if (c == '.' || c == '_' || c == '-') {
            next = true;
            continue;
        }
        if (next) {
            buf.append(c);
            next = false;
        }
    }
}

