private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    // Create a sorted copy of the keys
    List<K> sorted = new ArrayList<>(keys);
    Collections.sort((List)sorted); // raw cast to avoid generic bounds
    // Map each key to its maximum lower bound
    Map<K, Integer> lowerMap = new HashMap<>();
    Integer prev = null;
    for (K k : sorted){
        if (prev != null){
            lowerMap.put(k, prev);
        } else {
            lowerMap.put(k, null);
        }
        if (prev == null || !k.equals(prev)){
            prev = (Integer)k;
        }
    }
    // Preserve original order
    for (K k : keys){
        result.add(lowerMap.get(k));
    }
    return result;
}

private void pop(final String descriptor) {
    int count = 0;
    int i = 0;
    if (descriptor.charAt(0) == '(') {
        i = 1;
        while (descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == '[') {
                i++;
                continue;
            }
            if (c == 'L') {
                i++;
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
            }
            count++;
            i++;
        }
    } else {
        // single type descriptor
        char c = descriptor.charAt(0);
        if (c == '[') {
            while (descriptor.charAt(i) == '[') {
                i++;
            }
            if (descriptor.charAt(i) == 'L') {
                i++;
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
            }
        } else if (c == 'L') {
            i++;
            while (descriptor.charAt(i) != ';') {
                i++;
            }
        }
        count = 1;
    }
    for (int j = 0; j < count; j++) {
        outputFrameStack.pop();
    }
}

