public static String applyRelativePath(String path,String relativePath){
    if (relativePath == null || relativePath.isEmpty()) return path;
    if (path == null || path.isEmpty()) return relativePath;
    String[] baseParts = path.split("/");
    String[] relParts = relativePath.split("/");
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    if (path.startsWith("/")) {
        stack.addLast("");
    }
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }
    StringBuilder sb = new StringBuilder();
    for (String seg : stack) {
        if (seg.isEmpty()) {
            sb.append("/");
        } else {
            if (sb.length() > 0 && sb.charAt(sb.length() - 1) != '/') sb.append("/");
            sb.append(seg);
        }
    }
    if (sb.length() == 0) return ".";
    return sb.toString();
}

